//
//! The build half of mimalloc's runtime-loading route: three modules and one
//! generated file.
//!
//! An SDK that ships the runtime route calls `createModule` in place of
//! `translate.createModule()` and imports what comes back as its `c` module.
//! Nothing here links the native library. That is the point: in this
//! configuration the symbols arrive through the platform loader at run time,
//! and linking the archive as well would make the linker demand them before
//! `load` ever runs.
//!
//!   rt        runtime/loader.zig, the reusable core. Pure Zig; imported by the
//!             facade in both configurations, because `LoadSource` and
//!             `LoadError` are this SDK's public types and must be the same
//!             types whichever configuration is built.
//!   library   runtime/library.zig, this SDK's descriptor: the namespaced
//!             synchronization binding and the one load-time check.
//!   dispatch  generated by runtime/generate.zig from the real translation
//!             output: the table, the wrappers, `load`, and the re-exported
//!             translated namespace. It imports `rt`, `library` and the
//!             generator's patched translation as `c_native`, which imports the
//!             dispatch back as `c_routed`.
//!   sync.c    compiled into the dispatch with `-DRT_SYNC_PREFIX=mimalloc_rt`,
//!             so its symbols cannot collide with another SDK's.
//!
//! ## The one thing a caller must not do
//!
//! Do not link the compiled C archive into a module that imports this dispatch.
//! The facade's `c` import is the dispatch, and nothing else in the graph should
//! reference the library, or the linker resolves the symbols statically and the
//! runtime route silently becomes a linked one.
//!
//! ## What is routed, and what is not
//!
//! The translated header for this SDK is `zig/translate.h`, which includes
//! exactly `<mimalloc.h>` and defines no macro. That header declares every
//! `mi_*` entry point of the v3 API and no exported data object, and every one
//! of those names is routed: a provider that does not export the whole
//! header-declared allocator surface is refused rather than half used.
//! `provider_optional` is therefore empty and is written out rather than
//! omitted, so that adding a header with an optional entry point is a change in
//! this file with a name in it.
//!
//! `provider_excluded` is not empty, and both of its names are upstream's own
//! bug rather than a choice about this build: `mi_collect_reduce`
//! (`include/mimalloc.h:435`) and `mi_stats_merge` (`include/mimalloc.h:438`)
//! are declared in the public header's `Deprecated` block and defined in no
//! translation unit of the v3.5.3 source closure. A required set containing
//! them would fail every load on every platform. `runtime/library.zig` says the
//! same thing at length and the Zig facade calls neither.
//!
//! ## The C library's own three headers
//!
//! `<mimalloc.h>` opens `<stddef.h>` (`include/mimalloc.h:98`), `<stdbool.h>`
//! (`:99`) and `<assert.h>` (`:100`), and stops there. Unlike most headers in
//! this workspace that is a very small closure:
//!
//!   * `<stddef.h>` and `<stdbool.h>` declare no function in any libc family
//!     this package can be configured for. Read in the pinned Zig 0.16.0
//!     distribution's `lib/libc/include`, six of the seven families carry
//!     nothing at all; the two exceptions are listed below.
//!   * `<assert.h>` declares the assertion-failure entry point and nothing
//!     else. On Darwin it reaches `<_assert.h>`, whose only declaration is
//!     `__assert_rtn`.
//!
//! `<mimalloc-stats.h>` is deliberately **not** in `zig/translate.h`. It opens
//! `<string.h>` (`include/mimalloc-stats.h:12`) and `<stdint.h>` (`:13`), which
//! would drag the C library's entire `string.h` surface into the translation
//! and require a several-hundred-name noise list that this build would then
//! have to keep honest for six target families. The statistics structures are
//! also fixed-layout tables of `size_t` counters (`include/mimalloc-stats.h:106-121`)
//! whose shape upstream extends between minor versions; modelling them in Zig
//! by hand would be re-deriving a value upstream defines, which this workspace's
//! rules forbid. The printed-statistics entry points the facade does use -
//! `mi_stats_print_out`, `mi_process_info`, `mi_options_print_out` - are all
//! declared in `include/mimalloc.h` itself (`:441`, `:204`, `:202`) and are
//! therefore reached without the stats header. See `FORK-NOTES.md`.
//!
//! The list below is the union, over every libc family this package can be
//! configured for, of the function and object names that reach the translation
//! through that closure. It was read out of the pinned Zig distribution's own
//! headers rather than out of a `translate-c` run, because this build has not
//! been executed yet; each name is cited below with the file it came from.
//!
//! The families are the ones `lib/libc/include` holds for a target this package
//! can be built for: `any-darwin-any`, `any-windows-any`, `generic-glibc`,
//! `generic-musl`, `generic-freebsd`, `generic-netbsd` and `generic-openbsd`.
//! `wasm32-wasi` resolves `generic-musl`.
//!
//! It is a union across families on purpose: a name a given target's libc does
//! not declare never appears in that target's translation and the entry costs
//! nothing, while a name that was missing would be routed and would turn every
//! load on that family into a `MissingSymbol`.
//!
//! ### The list is comma-separated, and every line ends with one
//!
//! `runtime/generate.zig` reads these three lists through
//! `std.mem.splitScalar(u8, list, ',')` followed by a whitespace trim, and a
//! Zig multiline string literal concatenates its lines with nothing between
//! them. A line that does not end in a comma glues its last name to the first
//! name of the next line into one token, and that token matches neither
//! declaration: both real names are lost and both get routed. The commas are
//! load-bearing, not decoration.
const std = @import("std");

/// The prefix `runtime/sync.c` is compiled with.
///
/// `runtime/library.zig` declares the same prefix in the symbol names it binds.
/// The two must agree, and a build where they do not fails to link, which is
/// the whole error report: there is no runtime path that could hide it.
///
/// A build that needs a second, independent instance of this SDK in one binary
/// should change this value *and* the prefix in `runtime/library.zig`, and then
/// give the second instance its own copy of both files. Nothing else in the
/// package assumes one instance.
const sync_prefix = "mimalloc_rt";

/// `extern` declarations that are the C library's, not mimalloc's.
///
/// See "The C library's own three headers" above for where each name comes from
/// and why leaving one out is a load-time failure rather than a detail.
///
/// `lib/libc/include` in the pinned Zig 0.16.0 distribution, cited by path:
///
///   generic-glibc/assert.h:95    __assert_fail
///   generic-glibc/assert.h:100   __assert_perror_fail
///   generic-glibc/assert.h:107   __assert
///   generic-glibc/assert.h:115   __assert_single_arg
///   generic-musl/assert.h:19     __assert_fail
///   generic-freebsd/assert.h:81  __assert
///   generic-netbsd/assert.h:101  __assert
///   generic-netbsd/assert.h:102  __assert13
///   generic-netbsd/assert.h:103  __diagassert
///   generic-netbsd/assert.h:104  __diagassert13
///   generic-openbsd/assert.h:70  __assert
///   generic-openbsd/assert.h:71  __assert2
///   any-darwin-any/_assert.h:63  __assert_rtn
///   any-windows-any/assert.h:24  _wassert
///   any-windows-any/assert.h:25  _assert
///   any-windows-any/stddef.h:18  _errno
///   any-windows-any/stddef.h:20  _set_errno
///   any-windows-any/stddef.h:21  _get_errno
///   any-windows-any/stddef.h:24  __threadid
///   any-windows-any/stddef.h:26  __threadhandle
///   generic-openbsd/stddef.h:78  __max_align_ll
///   generic-openbsd/stddef.h:79  __max_align_ld
///
/// None of them is an `mi_` name, so nothing mimalloc declares is de-routed by
/// listing it, and each is listed by exact name rather than by a `__` prefix
/// rule - a prefix rule would also swallow `_mi_` internal names if a header
/// ever exposed one.
const libc_noise =
    \\__assert,__assert13,__assert2,__assert_fail,__assert_perror_fail,__assert_rtn,
    \\__assert_single_arg,__diagassert,__diagassert13,_assert,_errno,_get_errno,
    \\_set_errno,_wassert,__threadhandle,__threadid,__max_align_ld,__max_align_ll,
    \\
;

/// `extern` declarations the provider may legitimately not have.
///
/// None. Every entry point `mimalloc.h` declares is expected from a provider,
/// except the two in `provider_excluded` below, and a provider that does not
/// export the rest is refused rather than half used. The list is spelled out so
/// that adding a header with an optional entry point is a build-file change
/// with a name in it.
const provider_optional = "";

/// `extern` declarations this build does not require a provider to export.
///
/// Two, and both are upstream's. See the module comment: they are declared in
/// `include/mimalloc.h` and defined nowhere in the source closure, so requiring
/// them would refuse every provider this loader is for.
///
/// A name here is routed and optional rather than direct, so the declaration is
/// still a routed call rather than a reference the C library has to satisfy;
/// only `libc_noise` above stays direct.
const provider_excluded = "mi_collect_reduce,mi_stats_merge";

/// The loader core, for a *linked* build to import.
///
/// A linked build has no dispatch, so the facade needs the core module itself
/// for the two public types `LoadSource` and `LoadError`: they are this SDK's
/// types and they must be the same types a caller names in either
/// configuration. It costs a linked build two declarations and no code, since
/// nothing else in that module is referenced until a configuration actually
/// instantiates the loader.
///
/// A runtime-loading build must *not* import this separately: `createModule`
/// makes the one core instance the dispatch uses, and the dispatch re-exports
/// the two types from it. Two instances would be two sets of types, and a
/// consumer would be naming one while `load` expects the other.
pub fn createCoreModule(
    b: *std.Build,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    return b.createModule(.{
        .root_source_file = b.path("runtime/loader.zig"),
        .target = target,
        .optimize = optimize,
        // The Unix backend calls `dlopen`, which is libc. Nothing in this module
        // is compiled into a linked build, so this costs nothing there.
        .link_libc = true,
    });
}

/// The runtime-loaded `c` module for one target.
///
/// `translate` is the translation step for that same target and configuration;
/// its output is read by the generator, so the dispatch describes the headers
/// this build actually selected rather than another one.
pub fn createModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    const core = createCoreModule(b, target, optimize);

    const library = b.createModule(.{
        .root_source_file = b.path("runtime/library.zig"),
        .target = target,
        .optimize = optimize,
    });
    library.addImport("rt", core);

    return createDispatchModule(b, translate, target, optimize, core, library);
}

const GeneratedSources = struct {
    native: std.Build.LazyPath,
    dispatch: std.Build.LazyPath,
};

fn createDispatchModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
    core: *std.Build.Module,
    library: *std.Build.Module,
) *std.Build.Module {
    const sources = generateDispatch(b, translate, target);

    const dispatch = b.createModule(.{
        .root_source_file = sources.dispatch,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    dispatch.addImport("rt", core);
    dispatch.addImport("library", library);
    // The translated headers, under a name that says what it is. Every type and
    // constant in the dispatch is re-exported from here rather than restated, so
    // `c.mi_heap_t` in a facade and `c_native.mi_heap_t` in the dispatch are one
    // type.
    //
    // The root is the generator's *patched* translation, not the raw one the
    // translate step wrote. `const __root = @import("c_routed");` is what makes
    // a macro-expanded struct member that names a library function resolve to
    // the routed wrapper rather than escaping to a native `extern` this route
    // never links. That repointing is why the two modules import each other.
    const native = b.createModule(.{
        .root_source_file = sources.native,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    native.addImport("c_routed", dispatch);
    dispatch.addImport("c_native", native);
    dispatch.addCSourceFiles(.{
        .files = &.{"runtime/sync.c"},
        .flags = &.{b.fmt("-DRT_SYNC_PREFIX={s}", .{sync_prefix})},
        .language = .c,
    });
    return dispatch;
}

/// Runs the generator over the translation step's real output.
///
/// The generator is a host program built and run by this build, so the dispatch
/// is produced for the target being built from that target's own translation.
/// Nothing is cached across configurations: a different header configuration
/// produces a different translation step output, which produces a different
/// dispatch.
fn generateDispatch(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
) GeneratedSources {
    const generator = b.addExecutable(.{
        .name = b.fmt("mimalloc-runtime-generate-{s}", .{
            target.result.zigTriple(b.allocator) catch @panic("unspellable target"),
        }),
        .root_module = b.createModule(.{
            .root_source_file = b.path("runtime/generate.zig"),
            .target = b.graph.host,
            .optimize = .Debug,
        }),
    });

    const run = b.addRunArtifact(generator);
    run.addArg("--library");
    run.addArg("mimalloc");
    run.addArg("--translate");
    run.addFileArg(translate.getOutput());
    if (libc_noise.len != 0) {
        run.addArg("--noise");
        run.addArg(libc_noise);
    }
    if (provider_optional.len != 0) {
        run.addArg("--optional");
        run.addArg(provider_optional);
    }
    if (provider_excluded.len != 0) {
        run.addArg("--exclude");
        run.addArg(provider_excluded);
    }
    run.addArg("--native-output");
    const native_source = run.addOutputFileArg("native.zig");
    run.addArg("--output");
    const dispatch_source = run.addOutputFileArg("dispatch.zig");
    return .{ .native = native_source, .dispatch = dispatch_source };
}
